'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),overlay=document.getElementById('overlay');
const W=960,H=600,keys={},mouse={x:600,y:300,down:false};
const LEVELS=[
 {name:'BIDEN',subtitle:'THE ICE-CREAM SUMMIT',hint:'Dodge the scoops. Lecterns block movement, not bullets.',floor:'#252c3c',grid:'#303c50',accent:'#90c4ff',boss:'BIDEN / SCOOP COMMANDER',count:15,hp:105,roster:['chaser','shooter','charger','shield'],obstacles:[{x:260,y:225,w:60,h:95},{x:640,y:225,w:60,h:95}]},
 {name:'TRADE WAR',subtitle:'NOTHING TO DECLARE',hint:'Conveyors push everyone. Tax the crowd before it closes in.',floor:'#2c302a',grid:'#3b4439',accent:'#e7ca7b',boss:'THE TRADE DEFICIT',count:21,hp:155,roster:['charger','turret','shield','shooter','splitter','chaser'],belts:[{x:115,y:165,w:730,h:60,dir:1},{x:115,y:385,w:730,h:60,dir:-1}]},
 {name:'IRAN',subtitle:'THE ESCALATION MACHINE',hint:'Red circles explode after a warning. They hurt enemies too.',floor:'#362a32',grid:'#493640',accent:'#f3a47e',boss:'THE WAR MACHINE / MADE BY YOUR DECISIONS',count:24,hp:190,roster:['shooter','turret','charger','splitter','shield','chaser']}
];
const TYPES={chaser:{hp:3,r:16,speed:90,color:'#bbd66a'},charger:{hp:6,r:20,speed:48,color:'#ed946b'},shooter:{hp:4,r:17,speed:65,color:'#db96cc'},turret:{hp:5,r:19,speed:0,color:'#c8b0fa'},shield:{hp:7,r:21,speed:67,color:'#7fc8d0'},splitter:{hp:5,r:21,speed:72,color:'#efa8a1'},mini:{hp:1,r:10,speed:145,color:'#f4bdaf'}};
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let state='menu',wave=0,phase='mobs',score=0,player,enemies=[],bullets=[],shots=[],particles=[],hazards=[],spawned=0,total=0,spawnTimer=0,time=0,fire=0,shake=0,last=0,sound=false,audio,upgrades=[],kills=0,uid=0,field=null,hazardTimer=4,announcement='',announceTimer=0,stamp=0,touchMove=null,touchOrigin=null;
function tone(f=250,d=.07,type='square',v=.025){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,f/2),audio.currentTime+d);g.gain.setValueAtTime(v,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch(e){}}
function burst(x,y,color,n=12){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),s=rand(30,220);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.2,.6),color})}}
function show(html){overlay.innerHTML=html;overlay.classList.remove('hidden')}
function announce(text,d=3){announcement=text;announceTimer=d}
function reset(){player={x:480,y:400,r:14,hp:6,maxhp:6,speed:220,damage:1,rate:.19,multi:1,cd:0,jump:0,inv:0,tariffCd:0,dx:1,dy:0};wave=0;score=0;kills=0;time=0;upgrades=[];particles=[];fire=0;shake=0;nextLevel();canvas.focus()}
function clearCombat(){enemies=[];bullets=[];shots=[];hazards=[];field=null;spawned=0;stamp=0;touchMove=null;touchOrigin=null;mouse.down=false}
function nextLevel(){clearCombat();wave++;phase='mobs';spawnTimer=1;total=LEVELS[wave-1].count;hazardTimer=4;player.x=480;player.y=420;player.jump=0;player.cd=0;player.tariffCd=0;player.inv=2;state='play';overlay.classList.add('hidden');announce('CHAPTER '+wave+' / '+LEVELS[wave-1].name,3.5);hud()}
function spawn(type,position){const boss=type==='boss',cfg=boss?{hp:LEVELS[wave-1].hp,r:wave===1?32:43,speed:30,color:'#ad8bd9'}:TYPES[type];let edge=Math.floor(rand(0,4)),x=edge===0?48:edge===1?W-48:rand(60,W-60),y=edge===2?85:edge===3?H-45:rand(90,H-50);if(Math.hypot(x-player.x,y-player.y)<170){x=player.x<W/2?W-60:60;y=player.y<H/2?H-60:90}if(position){x=position.x;y=position.y}if(boss){x=480;y=145}const e={...cfg,id:uid++,x,y,type,maxhp:cfg.hp,t:rand(1,1.8),stun:0,flash:0,age:0,charge:0,vx:0,vy:0,tax:0,broken:0,face:Math.PI/2,bossPhase:0};enemies.push(e);return e}
function beginBoss(){phase='boss';bullets=[];shots=[];hazards=[];field=null;player.inv=2;spawn('boss');announce(LEVELS[wave-1].boss,3);tone(90,.3,'sawtooth')}
const choices=[{name:'Executive order',icon:'ϟ',desc:'30% faster firing.',apply:()=>player.rate*=.7},{name:'More. Much more.',icon:'⋔',desc:'Two extra projectiles per shot.',apply:()=>player.multi+=2},{name:'Golden standard',icon:'✦',desc:'+1 damage per projectile.',apply:()=>player.damage++}];
function upgrade(){state='upgrade';mouse.down=false;touchMove=null;show('<div class="tag">CHAPTER '+wave+' CLEARED</div><h2>A tremendous<br><em>opportunity.</em></h2><p>Recover 2 hearts. Choose your next advantage.<br>Next: '+LEVELS[wave].name+'</p><div class="choices">'+choices.map((u,i)=>'<button class="choice" data-choice="'+i+'"><span>'+u.icon+'</span><b>'+u.name+'</b><small>'+u.desc+'</small></button>').join('')+'</div>');overlay.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>chooseUpgrade(+b.dataset.choice))}
function chooseUpgrade(i){if(state!=='upgrade'||!choices[i])return;choices[i].apply();upgrades.push(choices[i].name);player.hp=Math.min(player.maxhp,player.hp+2);nextLevel()}
function end(win){state=win?'win':'dead';mouse.down=false;touchMove=null;hud();tone(win?650:100,.5,'sawtooth');show('<div class="tag">'+(win?'THREE CAMPAIGNS. ONE VERY STRANGE VICTORY.':'CAMPAIGN ENDED')+'</div><h2>'+(win?'Victory.<br><em>At what cost?</em>':'The campaign<br><em>got you.</em>')+'</h2><p>'+(win?'The war machine is down. The consequences remain.':'Try a different build. Use tariffs to create breathing room.')+'<br>Score '+score+' · '+kills+' enemies · '+Math.floor(time)+' seconds</p><button class="primary" id="again">RUN IT BACK ↗</button>');document.getElementById('again').onclick=reset}
function hud(){document.getElementById('health').textContent='♥ '.repeat(player?player.hp:6)+'♡ '.repeat(player?player.maxhp-player.hp:0);document.getElementById('score').textContent=String(score).padStart(4,'0');document.getElementById('wave').textContent=(wave||'—')+' / 3';document.getElementById('jumptext').textContent=player&&player.cd>0?player.cd.toFixed(1)+'s':'READY';document.getElementById('jumpmeter').style.width=(player?(1-player.cd/1.5)*100:100)+'%';document.getElementById('tarifftext').textContent=field?'ACTIVE '+field.life.toFixed(1)+'s':player&&player.tariffCd>0?player.tariffCd.toFixed(1)+'s':'READY';document.getElementById('tariffmeter').style.width=(player?(1-player.tariffCd/12)*100:100)+'%';document.getElementById('build').innerHTML='<b>✦ Golden Blaster</b><br>＋ Q: Tariff zone<br>'+ (upgrades.length?upgrades.map(u=>'＋ '+u).join('<br>'):'<span style="font-size:10px">Defeat bosses to choose upgrades.</span>')}
function jump(){if(state!=='play'||player.cd>0)return;player.jump=.58;player.cd=1.5;tone(390,.16,'sine');burst(player.x,player.y,'#d9fb76',8)}
function tariff(){if(state!=='play'||player.tariffCd>0)return;field={x:player.x,y:player.y,r:170,life:5};player.tariffCd=12;burst(player.x,player.y,'#ffe087',30);tone(600,.23,'triangle');hud()}
function hurt(){if(player.inv>0||player.jump>0||state!=='play')return;player.hp--;player.inv=1.3;shake=12;burst(player.x,player.y,'#ff855c',20);tone(110,.15,'sawtooth');if(player.hp<=0)end(false)}
function inRect(p,b){return p.x>b.x&&p.x<b.x+b.w&&p.y>b.y&&p.y<b.y+b.h}
function resolveBody(p){p.x=clamp(p.x,28+p.r,W-28-p.r);p.y=clamp(p.y,75+p.r,H-28-p.r);for(const b of LEVELS[wave-1].obstacles||[]){const x=clamp(p.x,b.x,b.x+b.w),y=clamp(p.y,b.y,b.y+b.h);let dx=p.x-x,dy=p.y-y,d=Math.hypot(dx,dy);if(d<p.r){if(d>0){p.x=x+dx/d*p.r;p.y=y+dy/d*p.r}else{const sides=[{d:p.x-b.x,x:b.x-p.r,y:p.y},{d:b.x+b.w-p.x,x:b.x+b.w+p.r,y:p.y},{d:p.y-b.y,x:p.x,y:b.y-p.r},{d:b.y+b.h-p.y,x:p.x,y:b.y+b.h+p.r}].sort((a,b)=>a.d-b.d);p.x=sides[0].x;p.y=sides[0].y}}}}
function conveyor(p,dt){if(p===player&&player.jump>0)return;for(const b of LEVELS[wave-1].belts||[])if(inRect(p,b))p.x+=b.dir*95*dt}
function enemyBullet(x,y,a,s=180,r=5,homing=false){bullets.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,r,life:7,homing})}
function warning(x,y,r=65,delay=1.45){hazards.push({x:clamp(x,50,W-50),y:clamp(y,90,H-50),r,t:delay,max:delay,blast:0,done:false})}
function updateHazards(dt){for(const h of hazards){h.t-=dt;if(h.t<=0&&!h.done){h.done=true;h.blast=.42;burst(h.x,h.y,'#ffa468',28);shake=10;tone(65,.2,'sawtooth');if(distance(h,player)<h.r+player.r)hurt();for(const e of enemies)if(distance(h,e)<h.r+e.r){e.hp-=e.type==='boss'?5:9;e.flash=.2}}if(h.done)h.blast-=dt}hazards=hazards.filter(h=>!h.done||h.blast>0)}
function fireBoss(e,a){if(wave===1){for(let i=-2;i<=2;i++)enemyBullet(e.x,e.y,a+i*.28,135,8);enemyBullet(e.x,e.y,a,105,11,true);e.t=e.hp<e.maxhp*.5?1.0:1.5}else if(wave===2){for(let i=0;i<12;i++)enemyBullet(e.x,e.y,i*Math.PI/6+e.age*.42,150,6);for(let i=-1;i<=1;i++)enemyBullet(e.x,e.y,a+i*.12,230);e.t=e.hp<e.maxhp*.5?.9:1.3}else{const n=e.hp<e.maxhp*.5?14:10;for(let i=0;i<n;i++)enemyBullet(e.x,e.y,i*2*Math.PI/n+e.age*.5,155);warning(player.x,player.y,60,1.45);e.t=e.hp<e.maxhp*.5?1:1.5}}
function updateEnemies(dt){for(const e of enemies){if(e.hp<=0)continue;e.age+=dt;e.flash=Math.max(0,e.flash-dt);e.stun=Math.max(0,e.stun-dt);e.broken=Math.max(0,e.broken-dt);const inside=field&&distance(e,field)<field.r+e.r;e.tax=inside?1:Math.max(0,e.tax-dt);const taxed=e.tax>0,boss=e.type==='boss',speedScale=taxed?(boss?.8:.6):1,attackScale=taxed&&!boss?1/1.3:1;e.t-=dt*attackScale;if(e.stun>0)continue;const a=Math.atan2(player.y-e.y,player.x-e.x);e.face=a;
if(boss){const p=e.hp<e.maxhp*.35?2:e.hp<e.maxhp*.68?1:0;if(p>e.bossPhase){e.bossPhase=p;if(wave===3){stamp=3;announce('MISSION ACCOMPLISHED… AGAIN.',3);for(let i=0;i<3+p;i++)warning(rand(90,870),rand(130,520),70,2.2)}}e.x+=Math.cos(a)*e.speed*speedScale*dt;e.y+=Math.sin(a)*e.speed*speedScale*dt;if(e.t<=0)fireBoss(e,a)}
else if(e.type==='charger'){if(e.charge>0){e.charge-=dt;e.x+=e.vx*speedScale*dt;e.y+=e.vy*speedScale*dt}else if(e.t<=0){e.charge=.45;e.vx=Math.cos(a)*420;e.vy=Math.sin(a)*420;e.t=2.1}else{e.x+=Math.cos(a)*e.speed*speedScale*dt;e.y+=Math.sin(a)*e.speed*speedScale*dt}}
else if(e.type==='turret'){if(e.t<=0){for(let i=-2;i<=2;i++)enemyBullet(e.x,e.y,a+i*.23,165);e.t=2.1}}
else if(e.type==='shooter'){if(distance(player,e)>245){e.x+=Math.cos(a)*e.speed*speedScale*dt;e.y+=Math.sin(a)*e.speed*speedScale*dt}if(e.t<=0){enemyBullet(e.x,e.y,a,185);e.t=1.65}}
else{e.x+=Math.cos(a)*e.speed*speedScale*dt;e.y+=Math.sin(a)*e.speed*speedScale*dt}conveyor(e,dt);resolveBody(e);if(distance(e,player)<e.r+player.r)hurt()}}
function shieldBlocks(e,s){return e.type==='shield'&&e.broken<=0&&e.stun<=0&&Math.cos(Math.atan2(s.y-e.y,s.x-e.x)-e.face)>.25}
function reap(){const dead=enemies.filter(e=>e.hp<=0);enemies=enemies.filter(e=>e.hp>0);for(const e of dead){score+=e.type==='boss'?1000:e.type==='mini'?15:50;kills++;burst(e.x,e.y,e.color,22);tone(220,.08,'triangle');shake=Math.max(shake,3);if(e.type==='splitter')for(const dir of [-1,1])spawn('mini',{x:clamp(e.x+dir*17,45,915),y:e.y})}}
function update(dt){time+=dt;announceTimer=Math.max(0,announceTimer-dt);stamp=Math.max(0,stamp-dt);player.inv=Math.max(0,player.inv-dt);player.cd=Math.max(0,player.cd-dt);player.tariffCd=Math.max(0,player.tariffCd-dt);if(field){field.life-=dt;if(field.life<=0)field=null}const wasJumping=player.jump>0;player.jump=Math.max(0,player.jump-dt);if(wasJumping&&player.jump===0){burst(player.x,player.y,'#dafb89',22);shake=5;for(const e of enemies)if(distance(e,player)<e.r+65){e.stun=1.5;e.broken=3;e.hp-=4;e.flash=.12}}
let mx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),my=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0);if(touchMove){mx=touchMove.x;my=touchMove.y}const norm=Math.hypot(mx,my);if(norm){mx/=Math.max(1,norm);my/=Math.max(1,norm);player.dx=mx;player.dy=my}const speed=player.speed*dt*(player.jump>0?1.65:1);player.x+=mx*speed;player.y+=my*speed;conveyor(player,dt);resolveBody(player);
fire-=dt;if((mouse.down||touchMove)&&fire<=0){fire=player.rate;let target=mouse;if(touchMove)target=enemies.reduce((a,b)=>!a||distance(player,b)<distance(player,a)?b:a,null)||{x:player.x+1,y:player.y};let angle=Math.atan2(target.y-player.y,target.x-player.x);for(let i=0;i<player.multi;i++){let a=angle+(i-(player.multi-1)/2)*.15;shots.push({x:player.x,y:player.y-10,vx:Math.cos(a)*620,vy:Math.sin(a)*620,r:5,damage:player.damage,life:1.8})}tone(460,.04,'triangle',.02)}
spawnTimer-=dt;if(phase==='mobs'&&spawned<total&&spawnTimer<=0){spawnTimer=Math.max(.55,1.15-wave*.12);const roster=LEVELS[wave-1].roster;spawn(roster[spawned%roster.length]);spawned++}if(wave===3){hazardTimer-=dt;if(hazardTimer<=0){hazardTimer=phase==='boss'?3.8:4.5;warning(player.x+rand(-55,55),player.y+rand(-55,55),65);if(phase==='boss')warning(rand(80,880),rand(120,520),65)}}
updateEnemies(dt);for(const s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;for(const e of enemies){if(e.hp>0&&s.life>0&&distance(s,e)<e.r+s.r){s.life=0;if(shieldBlocks(e,s)){burst(s.x,s.y,'#a7eff9',4);tone(700,.025,'sine',.01)}else{e.hp-=s.damage;e.flash=.09;burst(s.x,s.y,'#ffee94',3)}break}}}
for(const b of bullets){if(b.homing){const speed=Math.hypot(b.vx,b.vy),a=Math.atan2(player.y-b.y,player.x-b.x),blend=dt*.7;b.vx=b.vx*(1-blend)+Math.cos(a)*speed*blend;b.vy=b.vy*(1-blend)+Math.sin(a)*speed*blend}b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(distance(b,player)<b.r+player.r&&player.jump<=0){hurt();b.life=0}}
updateHazards(dt);reap();shots=shots.filter(s=>s.life>0&&s.x>0&&s.x<W&&s.y>0&&s.y<H);bullets=bullets.filter(s=>s.life>0&&s.x>0&&s.x<W&&s.y>0&&s.y<H);if(state==='play'&&spawned>=total&&enemies.length===0){if(phase==='mobs')beginBoss();else if(wave===3)end(true);else upgrade()}hud()}
function ellipse(x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function person(x,y,biden=false,j=0){ctx.save();ctx.translate(x,y);ellipse(0,9,20,7,'#0006');ctx.translate(0,-Math.sin(j/.58*Math.PI)*33);if(j>0){ctx.strokeStyle='#d9fb76';ctx.beginPath();ctx.ellipse(0,9,25,10,0,0,7);ctx.stroke()}ctx.fillStyle='#111527';ctx.fillRect(-12,3,9,13);ctx.fillRect(4,3,9,13);ctx.fillStyle='#e8e4dd';ctx.fillRect(-14,-18,28,25);ctx.fillStyle=biden?'#354d68':'#24395a';ctx.fillRect(-17,-18,12,25);ctx.fillRect(5,-18,12,25);ctx.fillStyle=biden?'#7db8fb':'#f45c56';ctx.fillRect(-3,-16,6,20);ctx.fillStyle=biden?'#efc7a2':'#ffa45f';ctx.fillRect(-14,-39,28,25);ctx.fillRect(-17,-32,5,11);ctx.fillStyle=biden?'#e9edf0':'#ffd66d';ctx.fillRect(-15,-43,30,10);ctx.fillRect(-18,-39,24,7);ctx.fillRect(8,-35,7,6);ctx.fillStyle=biden?'#152131':'#8e532e';ctx.fillRect(-10,-29,biden?10:4,biden?6:3);ctx.fillRect(3,-29,biden?10:4,biden?6:3);if(biden){ctx.fillRect(-1,-28,5,2);ellipse(23,-21,8,8,'#f8b8d9');ctx.fillStyle='#c9a875';ctx.beginPath();ctx.moveTo(17,-17);ctx.lineTo(29,-17);ctx.lineTo(23,-4);ctx.fill()}ctx.fillStyle='#fff1cf';ctx.fillRect(0,-20,7,3);ctx.restore()}
function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);ellipse(0,e.r*.65,e.r*.9,e.r*.35,'#0005');ctx.translate(0,Math.sin(e.age*7)*2);const color=e.flash>0?'#fffce3':e.color;if(e.type==='boss'&&wave===1){ctx.save();ctx.scale(1.75,1.75);person(0,0,true);ctx.restore()}else if(e.type==='boss'&&wave===2){ctx.fillStyle='#b98e4f';ctx.fillRect(-49,-34,98,64);ctx.fillStyle='#efce7c';for(let x=-40;x<45;x+=14)ctx.fillRect(x,-28,4,51);ctx.fillStyle='#292b27';ctx.fillRect(-24,-21,49,25);ctx.fillStyle='#f5e4a0';ctx.font='bold 15px monospace';ctx.textAlign='center';ctx.fillText('DEFICIT',0,-3);ctx.fillStyle='#474a3a';ctx.fillRect(-54,26,108,12)}else if(e.type==='boss'){ctx.fillStyle=color;ctx.fillRect(-44,-27,88,53);ctx.fillStyle='#1e252b';ctx.fillRect(-53,20,106,19);ctx.fillStyle='#687e7a';ctx.fillRect(-28,-45,56,24);ctx.save();ctx.rotate(e.face);ctx.fillStyle='#e7b484';ctx.fillRect(0,-8,65,16);ctx.restore();ctx.fillStyle='#f7d28b';ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillText('ESCALATION',0,8)}else if(e.type==='charger'){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(0,-24);ctx.lineTo(24,15);ctx.lineTo(-24,15);ctx.fill();if(e.t<.5&&e.charge<=0){ctx.save();ctx.rotate(e.face);ctx.strokeStyle='#ffc19e';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(28,0);ctx.lineTo(65,0);ctx.moveTo(55,-8);ctx.lineTo(65,0);ctx.lineTo(55,8);ctx.stroke();ctx.restore()}}else if(e.type==='turret'){ctx.fillStyle='#685779';ctx.fillRect(-23,5,46,13);ellipse(0,-4,19,19,color);ctx.save();ctx.rotate(e.face);ctx.fillStyle='#e5cbfa';ctx.fillRect(0,-5,29,10);ctx.restore()}else{ellipse(0,-3,e.r,e.r,color);ctx.fillStyle=color;ctx.fillRect(-e.r,-21,7,16);ctx.fillRect(e.r-7,-21,7,16);if(e.type==='splitter'){ctx.strokeStyle='#ad626d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-2,-20);ctx.lineTo(4,-7);ctx.lineTo(-5,4);ctx.lineTo(2,15);ctx.stroke()}}
if(wave===2&&e.type==='charger'){ctx.strokeStyle='#ffdd8b';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-15,10);ctx.lineTo(-15,30);ctx.moveTo(15,10);ctx.lineTo(15,30);ctx.stroke()}if(wave===3&&e.type==='shooter'){ctx.strokeStyle='#e0bdd9';ctx.lineWidth=3;for(const wing of [-1,1]){ctx.beginPath();ctx.moveTo(wing*12,-8);ctx.lineTo(wing*31,-18);ctx.stroke();ellipse(wing*31,-18,13,3,'#e0bdd9')}}if(!(e.type==='boss')){ellipse(-e.r*.36,-7,4,5,'#30253a');ellipse(e.r*.36,-7,4,5,'#30253a')}if(e.type==='shield'&&e.broken<=0){ctx.strokeStyle='#b1eef5';ctx.lineWidth=7;ctx.beginPath();ctx.arc(0,0,e.r+5,e.face-1.25,e.face+1.25);ctx.stroke()}if(e.stun>0){ctx.fillStyle='#f8e79d';ctx.font='20px monospace';ctx.textAlign='center';ctx.fillText('✧',0,-e.r-14)}if(e.tax>0){ctx.fillStyle='#ffdd7b';ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillText('↓ TAXED',0,-e.r-24);ctx.strokeStyle='#f8d272';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(0,e.r*.6,e.r+5,8,0,0,7);ctx.stroke()}ctx.restore();if(e.hp<e.maxhp&&e.type!=='boss'){ctx.fillStyle='#151323';ctx.fillRect(e.x-18,e.y+e.r+9,36,4);ctx.fillStyle='#d9fb76';ctx.fillRect(e.x-18,e.y+e.r+9,36*Math.max(0,e.hp/e.maxhp),4)}}
function draw(){ctx.save();ctx.clearRect(0,0,W,H);const level=LEVELS[Math.max(0,wave-1)];ctx.fillStyle=level.floor;ctx.fillRect(0,0,W,H);ctx.translate(rand(-shake,shake),rand(-shake,shake));ctx.strokeStyle=level.grid;ctx.lineWidth=1;for(let x=24;x<W;x+=48){ctx.beginPath();ctx.moveTo(x,30);ctx.lineTo(x,H-22);ctx.stroke()}for(let y=24;y<H;y+=48){ctx.beginPath();ctx.moveTo(24,y);ctx.lineTo(W-24,y);ctx.stroke()}ctx.strokeStyle=level.accent;ctx.lineWidth=3;ctx.strokeRect(24,70,W-48,H-96);
for(const b of level.belts||[]){ctx.fillStyle='#161f1d';ctx.fillRect(b.x,b.y,b.w,b.h);ctx.strokeStyle='#7a967a';ctx.lineWidth=2;for(let x=b.x+10;x<b.x+b.w-20;x+=40){const xx=x+(time*35*b.dir%40);ctx.beginPath();ctx.moveTo(xx-b.dir*6,b.y+17);ctx.lineTo(xx+b.dir*7,b.y+30);ctx.lineTo(xx-b.dir*6,b.y+43);ctx.stroke()}}
for(const b of level.obstacles||[]){ellipse(b.x+b.w/2,b.y+b.h,b.w*.65,11,'#0005');ctx.fillStyle='#6d4c43';ctx.fillRect(b.x,b.y,b.w,b.h);ctx.fillStyle='#c6986e';ctx.fillRect(b.x-6,b.y,b.w+12,15);ellipse(b.x+b.w/2,b.y+50,15,15,'#27466d');ctx.fillStyle='#dae6ef';ctx.font='18px monospace';ctx.textAlign='center';ctx.fillText('★',b.x+b.w/2,b.y+57)}
if(field){const alpha=.10+Math.sin(time*9)*.025;ellipse(field.x,field.y,field.r,field.r,'rgba(255,217,114,'+alpha+')');ctx.strokeStyle='#f6d475';ctx.lineWidth=3;ctx.setLineDash([12,8]);ctx.beginPath();ctx.arc(field.x,field.y,field.r,0,7);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#ffe8a3';ctx.font='bold 13px monospace';ctx.textAlign='center';ctx.fillText('TARIFF ZONE · '+field.life.toFixed(1)+'s',field.x,field.y-field.r+22)}
for(const h of hazards){const p=1-Math.max(0,h.t)/h.max;ellipse(h.x,h.y,h.r,h.r,h.done?'#ffbc7280':'#ff654b24');ctx.strokeStyle=h.done?'#ffe5a9':'#ff896c';ctx.lineWidth=h.done?5:2;ctx.beginPath();ctx.arc(h.x,h.y,h.r*(h.done?1:Math.max(.1,p)),0,7);ctx.stroke();if(!h.done){ctx.fillStyle='#ffceab';ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillText('!',h.x,h.y-5);ctx.fillText(h.t.toFixed(1),h.x,h.y+12)}}
ctx.fillStyle=level.accent;ctx.font='bold 12px monospace';ctx.textAlign='left';ctx.fillText('0'+Math.max(1,wave)+' / '+level.name,40,32);ctx.fillStyle='#c7c1b7';ctx.font='10px monospace';ctx.fillText(level.hint,40,53);ctx.textAlign='right';ctx.fillText(phase==='boss'?'BOSS ENCOUNTER':Math.min(spawned,total)+' / '+total+' DISPATCHED',W-40,32);
for(const b of bullets){ellipse(b.x,b.y,b.r+3,b.r+3,'#ff659d26');ellipse(b.x,b.y,b.r,b.r,wave===1?'#ffd3eb':'#ff7d9a');ellipse(b.x-1,b.y-1,2,2,'#ffefdc');if(b.homing){ctx.fillStyle='#d8a76b';ctx.beginPath();ctx.moveTo(b.x-5,b.y+6);ctx.lineTo(b.x+5,b.y+6);ctx.lineTo(b.x,b.y+15);ctx.fill()}}
for(const s of shots){ctx.strokeStyle='#ffcf60';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x-s.vx*.017,s.y-s.vy*.017);ctx.stroke()}for(const e of enemies)drawEnemy(e);
if(player){if(player.inv<=0||Math.floor(player.inv*14)%2===0)person(player.x,player.y,false,player.jump);let target=mouse;if(touchMove)target=enemies.reduce((a,b)=>!a||distance(player,b)<distance(player,a)?b:a,null)||mouse;const a=Math.atan2(target.y-player.y,target.x-player.x);ctx.save();ctx.translate(player.x,player.y-11-Math.sin(player.jump/.58*Math.PI)*33);ctx.rotate(a);ctx.fillStyle='#8d6336';ctx.fillRect(7,-6,12,12);ctx.fillStyle='#ffe28b';ctx.fillRect(13,-5,22,10);ctx.fillStyle='#fff2bb';ctx.fillRect(30,-3,9,6);ctx.restore()}else person(480,330);
for(const p of particles){ctx.globalAlpha=Math.min(1,p.life*3);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,4,4)}ctx.globalAlpha=1;
const boss=enemies.find(e=>e.type==='boss');if(boss){ctx.fillStyle='#131221';ctx.fillRect(240,H-21,480,8);ctx.fillStyle=level.accent;ctx.fillRect(240,H-21,480*Math.max(0,boss.hp/boss.maxhp),8);ctx.fillStyle='#eee2dc';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText(level.boss,480,H-30)}
if(announceTimer>0){ctx.fillStyle='#131823dd';ctx.fillRect(160,98,640,48);ctx.fillStyle=level.accent;ctx.font='bold 19px monospace';ctx.textAlign='center';ctx.fillText(announcement,480,129)}if(stamp>0){ctx.save();ctx.translate(735,470);ctx.rotate(-.18);ctx.strokeStyle='#ff897b90';ctx.lineWidth=4;ctx.strokeRect(-142,-26,284,52);ctx.fillStyle='#ff897bb0';ctx.font='bold 17px monospace';ctx.textAlign='center';ctx.fillText('MISSION ACCOMPLISHED',0,6);ctx.restore()}
ctx.restore();if(state==='play'&&!touchMove){ctx.strokeStyle='#f6edc4b0';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(mouse.x,mouse.y,8,0,7);for(const sign of [-1,1]){ctx.moveTo(mouse.x+sign*5,mouse.y);ctx.lineTo(mouse.x+sign*13,mouse.y);ctx.moveTo(mouse.x,mouse.y+sign*5);ctx.lineTo(mouse.x,mouse.y+sign*13)}ctx.stroke()}}
function loop(t){const dt=Math.min((t-last)/1000,.033);last=t;if(state==='play')update(dt);if(['play','dead','win'].includes(state)){for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);shake=Math.max(0,shake-dt*45)}draw();requestAnimationFrame(loop)}
function pause(){if(state==='play'){state='paused';mouse.down=false;touchMove=null;touchOrigin=null;show('<div class="tag">TAKE A BREATHER</div><h2>Chaos can<br><em>wait.</em></h2><p>Your campaign is right where you left it.</p><button class="primary" id="resume">RESUME ↗</button>');document.getElementById('resume').onclick=pause}else if(state==='paused'){state='play';overlay.classList.add('hidden');canvas.focus()}}
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.key.toLowerCase()]=true;keys[e.key]=true;if(e.code==='Space'&&!e.repeat)jump();if(e.key.toLowerCase()==='q'&&!e.repeat)tariff();if((e.key.toLowerCase()==='p'||e.key==='Escape')&&!e.repeat)pause()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;keys[e.key]=false});window.addEventListener('blur',()=>{Object.keys(keys).forEach(k=>keys[k]=false);release();if(state==='play')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='play')pause()});
function coords(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height}}
canvas.addEventListener('pointermove',e=>{const p=coords(e);mouse.x=p.x;mouse.y=p.y;if(e.pointerType==='touch'&&touchOrigin)touchMove={x:clamp((p.x-touchOrigin.x)/60,-1,1),y:clamp((p.y-touchOrigin.y)/60,-1,1)}});canvas.addEventListener('pointerdown',e=>{if(state!=='play')return;canvas.setPointerCapture(e.pointerId);const p=coords(e);mouse.x=p.x;mouse.y=p.y;if(e.pointerType==='touch'){touchOrigin=p;touchMove={x:0,y:0}}else mouse.down=true});function release(){mouse.down=false;touchMove=null;touchOrigin=null}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);window.addEventListener('pointerup',e=>{if(e.target===canvas||e.pointerType!=='touch')release()});canvas.addEventListener('contextmenu',e=>e.preventDefault());document.getElementById('jump').onpointerdown=e=>{e.preventDefault();jump()};document.getElementById('tariff').onpointerdown=e=>{e.preventDefault();tariff()};document.getElementById('pause').onclick=pause;document.getElementById('sound').onclick=()=>{sound=!sound;document.getElementById('sound').textContent=sound?'♪ SOUND ON':'♪ SOUND OFF';tone(500)};document.getElementById('restart').onclick=reset;
show('<div class="tag">THREE CHAPTERS. QUESTIONABLE DECISIONS.</div><h2>The art of<br><em>the debuff.</em></h2><p>Biden → Trade War → Iran<br>One enemy wave + one boss per chapter.<br><b>Q</b>: 5s tariff zone · slows movement & attacks<br><b>SPACE</b>: dodge-jump · landing stuns & breaks shields</p><button class="primary" id="start">START THE CAMPAIGN ↗</button><div class="hint">WASD + MOUSE TO MOVE & SHOOT<br><br>TOUCH: DRAG TO MOVE & AUTO-FIRE · TAP SKILLS</div>');document.getElementById('start').onclick=reset;requestAnimationFrame(loop);
